SELECT 
FROM my_homework

    AND title   LIKE CONCAT('%', #{homeworkName}, '%')
                           AND c_id    = #{courseId}
                           AND teacher_id = #{teacherId}
                           AND status  = #{status}

ORDER BY create_time DESC

SELECT COUNT(1)
FROM my_homework
WHERE teacher_id = #{teacherId}

